import os,tempfile,subprocess
script="const root='http://127.0.0.1:17448';
async function json(u){let x=await fetch(u,{signal:AbortSignal.timeout(5000)});if(!x.ok)throw Error('http_'+x.status);return x.json()}
function norm(u){try{let x=new URL(String(u));return x.hostname.replace(/^www\./,'')==='chatgpt.com'?x.pathname.replace(/\/$/,''):''}catch{return ''}}
async function basic(target){
 return new Promise(resolve=>{
  const t0=performance.now();let ws,opened=false,done=false;
  const finish=(x)=>{if(done)return;done=true;clearTimeout(timer);try{ws?.close()}catch{}resolve({...x,opened,ms:Math.round(performance.now()-t0)})};
  const timer=setTimeout(()=>finish({ok:false,reason:'basic_cdp_timeout'}),3800);
  try{
   ws=new WebSocket(target);
   ws.addEventListener('open',()=>{opened=true;ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression:'2+2',awaitPromise:false,returnByValue:true}}))});
   ws.addEventListener('message',e=>{try{let o=JSON.parse(e.data);if(o.id===1)finish(o.result?.result?.value===4?{ok:true}:{ok:false,reason:o.error?'cdp_error':'wrong_value'})}catch{finish({ok:false,reason:'bad_json'})}});
   ws.addEventListener('error',()=>finish({ok:false,reason:'ws_error'}));
  }catch{finish({ok:false,reason:'ws_construct'})}
 })
}
async function main(){
 let [ps,cfg,ch]=await Promise.all([json(root+'/api/ai-profiles'),json(root+'/api/supervisor-watchdog?detect=0'),json(root+'/api/supervisor-watchdog/managed-chats?inspect=0')]);
 let ports=[...new Set((ps.aiProfiles||[]).filter(z=>z.provider==='chatgpt' && z.debugPort).map(z=>Number(z.debugPort)))].slice(0,12);
 let all=await Promise.all(ports.map(async port=>{try{return {port,list:await json('http://127.0.0.1:'+port+'/json/list')}}catch{return {port,list:[]}}}));
 let rows=await Promise.all((ch.chats||[]).map(async z=>{
  let want=norm(z.url),matches=all.flatMap(x=>(x.list||[]).filter(t=>norm(t.url)===want&&t.webSocketDebuggerUrl).map(t=>({port:x.port,t})));
  return {name:z.name,matches:matches.length,ports:matches.map(m=>m.port),basic:matches[0]?await basic(matches[0].t.webSocketDebuggerUrl):null};
 }));
 console.log(JSON.stringify({at:new Date().toISOString(),profiles:ports.length,debugTargetCounts:all.map(x=>x.list.length),rows}));
}
main().catch(e=>{console.log(JSON.stringify({error:String(e.message).slice(0,120)}));process.exitCode=1})"
with tempfile.TemporaryDirectory(prefix='bridge-r45-cdp-exact-') as folder:
 p=os.path.join(folder,'probe.js')
 with open(p,'w',encoding='utf-8') as f:f.write(script)
 try:
  z=subprocess.run(['node.exe',p],capture_output=True,text=True,timeout=45)
  print(z.stdout[-9000:])
  print('EXIT:'+str(z.returncode))
 except Exception as e:print('ERROR:'+type(e).__name__)
